const recallCards=[["若一个氨基酸的 pH 高于 pI，它通常带什么净电荷？","通常偏负。pH 升高使基团更易去质子化；pH>pI 时，平均净电荷从零继续向负方向移动。"],
["为什么 pI 不能理解为“分子没有电荷”？","pI 时平均净电荷为零，但两性离子形式同时含有 –NH₃⁺ 和 –COO⁻。"],
["为什么 Gly 在 Ramachandran 图上允许范围更大？","Gly 的侧链是 H，空间位阻小，因此更多 φ/ψ 组合不发生原子重叠。"],
["为什么 Pro 常打断 α 螺旋？","Pro 限制 φ 并常缺少可用于螺旋主链氢键的 N–H，因此常破坏 α 螺旋。"],
["肽键近似平面，蛋白质为什么还能折叠？","ω 转动受限，但相邻的 φ 和 ψ 单键仍可旋转；它们的受限组合塑造整个主链。"],
["α 螺旋的关键氢键在哪里？","第 n 个残基的主链 C=O 与第 n+4 个残基的主链 N–H 之间。"],
["β 折叠的“平行/反平行”描述什么？","相邻 β 股的 N→C 方向关系，而非两张片层是否完全平行摆放。"],
["模体与结构域的尺度差别是什么？","模体是局部重复组合；结构域更大，常可相对独立折叠并承担功能。"],
["Anfinsen 法则真正说明什么？","一级序列含有形成天然构象所需的化学信息，前提是条件合适；它不否定细胞内伴侣的作用。"],
["分子伴侣怎样帮助折叠？","它们暂时遮蔽暴露疏水表面或提供隔离空间，减少错误聚集，并不替蛋白决定最终序列信息。"],
["为什么 Cys 二硫键在胞质中通常不稳定？","胞质环境通常较还原，会促进二硫键还原为两个巯基。"],
["His 为什么常见于活性位点？","咪唑基 pKa 接近生理 pH，较容易在结合或催化过程中给出或接受质子。"],
["什么是兼职蛋白？","同一条多肽链在不同定位、寡聚状态或结合环境中承担两种以上独立功能，而不是依靠不同基因产物。"],
["为什么胶原每三个残基必须出现一个 Gly？","三股螺旋中心空间极小，只有侧链为 H 的 Gly 能够容纳；它解决的是紧密堆积，不是形成疏水核心。"],
["维生素 C 缺乏为什么影响胶原？","维生素 C 是脯氨酰和赖氨酰羟化酶维持催化所需铁还原态的辅助因子；羟化不足会降低三股螺旋稳定性和成熟交联。"],
["Mb 与 Hb 的氧结合曲线为什么不同？","Mb 只有一个位点，呈双曲线；Hb 的四个位点通过 T/R 构象耦联产生正协同，呈 S 形曲线。"],
["Hb 的 T 态和 R 态分别意味着什么？","T 态亚基界面更受约束、氧亲和力低；R 态氧亲和力高。O₂结合把平衡推向 R 态。"],
["Bohr 效应怎样帮助代谢活跃组织获得氧？","代谢产生的 H⁺和 CO₂稳定 Hb 的 T 态，降低氧亲和力，使 Hb 在低 pH、高 CO₂组织中释放更多氧。"],
["2,3-BPG 在哪里结合，产生什么结果？","它结合脱氧 Hb 两条 β 链间的正电中央空腔，稳定 T 态，使曲线右移并促进组织放氧。"],
["HbS 的一个 Glu→Val 突变为何能改变红细胞形状？","Val 在 Hb 表面制造疏水斑块；脱氧 HbS 通过异常疏水界面聚合成长纤维，进而拉扯红细胞发生镰变。"],
["固有无序蛋白为什么没有唯一稳定结构仍能发挥功能？","它们以构象集合存在，暴露多个短线性基序和修饰位点，并可在结合后折叠，适合调控和多伙伴识别。"]];
const quizzes=[{q:"蛋白质 X 的某 Lys 侧链处于 pH 10 的环境。相对 pH 7，它更可能发生什么变化？",a:["更易质子化","更易失去质子","必然形成二硫键","转变为 D-构型"],c:1,e:"pH 上升推动可电离基团去质子化。Lys 的具体比例还取决于局部微环境和 pKa。"},
{q:"某突变把一个螺旋内部的 Leu 换成 Pro。最直接的结构风险是？",a:["肽键全部变成 cis","α螺旋局部被破坏","产生新的二硫键","蛋白必然降解"],c:1,e:"Pro 限制 φ 并常缺少可用于螺旋主链氢键的 N–H，因此常破坏 α 螺旋；后续命运需实验判断。"},
{q:"为什么同一序列可能在不同条件下呈不同构象集合？",a:["一级结构毫无作用","环境改变了溶剂化、质子化和相互作用代价","肽键可以任意旋转","所有结构都等能"],c:1,e:"序列提供倾向，而 pH、氧化还原状态、配体和拥挤程度会改变能量景观。"},
{q:"一个 β 股的侧链通常朝哪里分布？",a:["都朝片层中央","交替伸向片层两面","都沿氢键方向","完全随机"],c:1,e:"β 折叠近似伸展的锯齿状主链使侧链交替位于片层两侧。"},
{q:"Anfinsen 实验不能直接推出下面哪一项？",a:["序列含有折叠信息","细胞中从不需要分子伴侣","适当条件下 RNase A 可复性","折叠受自由能驱动"],c:1,e:"细胞内存在聚集、翻译过程和拥挤等问题；许多蛋白需要伴侣辅助。"},
{q:"若要区分“pI”与“pKa”，最准确的说法是？",a:["两者都只属于溶液","pI 是净电荷为零的 pH，pKa 描述单个电离步骤","pKa 是蛋白质大小","pI 一定等于 7"],c:1,e:"pKa 关联某个可电离基团和其环境；pI 是整个分子电荷状态的结果。"},
{q:"把 Hb 的氧结合行为改造成更像 Mb，最可能观察到什么？",a:["曲线更接近双曲线且协同性下降","曲线一定完全右移","血红素数目增加","所有亚基变成 β 折叠"],c:0,e:"Mb 的单结合位点没有亚基间协同。若 Hb 的亚基耦联被削弱，S 形特征会减弱并趋向双曲线。"},
{q:"代谢旺盛组织局部 pH 下降、CO₂升高时，Hb 通常发生什么？",a:["稳定 R 态并更紧地抓住氧","稳定 T 态并释放更多氧","BPG 从血红素铁上脱落","Fe²⁺必然氧化成 Fe³⁺"],c:1,e:"Bohr 效应使 H⁺和 CO₂稳定低亲和力 T 态，从而把氧交给代谢旺盛组织。"},
{q:"胎儿 HbF 的氧亲和力高于成人 HbA，关键原因之一是？",a:["HbF 不含血红素","γ 链与 2,3-BPG 的结合较弱","HbF 只有一个亚基","HbF 的铁为 Fe³⁺"],c:1,e:"γ 链替代 β 链后，中央空腔与 BPG 的相互作用减弱，T 态稳定作用变小，因此 HbF 亲和力较高。"},
{q:"HbS 的 β6 Glu→Val 最直接改变了哪种性质？",a:["主链肽键数量","蛋白表面的电荷与疏水性","每个血红素的铁配位数","α 亚基数目"],c:1,e:"负电 Glu 换成疏水 Val，在表面产生异常疏水斑块，促成脱氧 HbS 分子间聚合。"},
{q:"预测一个未知蛋白的功能时，哪条证据最能建立因果关系？",a:["它与某酶序列相似","结构模型出现一个口袋","关键位点突变后结合或活性按预测改变","它含有很多带电残基"],c:2,e:"序列与结构提供假说；针对关键位点的实验改变功能，才能直接支持该位点与功能之间的因果联系。"}];
function renderRecall(){const host=document.querySelector('#recall-card');if(!host)return;let i=Number(localStorage.getItem('bio-recall-index')||0)%recallCards.length;const draw=()=>{const [q,a]=recallCards[i];host.innerHTML=`<p class="eyebrow">CARD ${i+1} / ${recallCards.length}</p><h2>${q}</h2><button class="primary" id="reveal">显示答案</button><div id="answer" hidden><p>${a}</p><div class="rate"><button data-rate="again">还不会</button><button data-rate="hard">有点模糊</button><button data-rate="good">能完整讲出</button></div></div>`;host.querySelector('#reveal').onclick=()=>{host.querySelector('#answer').hidden=false;host.querySelector('#reveal').hidden=true};host.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{localStorage.setItem('bio-recall-index',String((i+1)%recallCards.length));i=(i+1)%recallCards.length;draw()})};draw()}function renderPractice(){const host=document.querySelector('#quiz-list');if(!host)return;host.innerHTML=quizzes.map((x,i)=>`<article class="quiz"><p class="eyebrow">QUESTION ${i+1}</p><h3>${x.q}</h3>${x.a.map((a,j)=>`<button data-q="${i}" data-a="${j}">${String.fromCharCode(65+j)}. ${a}</button>`).join('')}<p class="explain" hidden></p></article>`).join('');host.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{const x=quizzes[+b.dataset.q],card=b.closest('.quiz');card.querySelectorAll('button').forEach(k=>k.disabled=true);b.classList.add(+b.dataset.a===x.c?'correct':'wrong');card.querySelectorAll('button')[x.c].classList.add('correct');const e=card.querySelector('.explain');e.hidden=false;e.textContent=x.e})}renderRecall();renderPractice();
